import java.io.*;
import java.util.*;

public class Main {
    static class Fenwick {
        int n;
        int[] tree;

        Fenwick(int n) {
            this.n = n;
            this.tree = new int[n + 2];
        }

        void add(int idx, int val) {
            while (idx <= n) {
                tree[idx] += val;
                idx += idx & -idx;
            }
        }

        int sum(int idx) {
            int res = 0;
            while (idx > 0) {
                res += tree[idx];
                idx -= idx & -idx;
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        long X1 = Long.parseLong(st.nextToken());
        long X2 = Long.parseLong(st.nextToken());

        int[] A = new int[N];
        int[] B = new int[N];
        long[] val1 = new long[N];
        long[] val2 = new long[N];

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            A[i] = Integer.parseInt(st.nextToken());
            B[i] = Integer.parseInt(st.nextToken());
            val1[i] = (long) A[i] * X1 + B[i];
            val2[i] = (long) A[i] * X2 + B[i];
        }

        Integer[] ord1 = new Integer[N];
        Integer[] ord2 = new Integer[N];

        for (int i = 0; i < N; i++) {
            ord1[i] = i;
            ord2[i] = i;
        }

        Arrays.sort(ord1, (i, j) -> {
            if (val1[i] != val1[j]) {
                return Long.compare(val1[i], val1[j]);
            }
            return Long.compare(A[j], A[i]);
        });

        Arrays.sort(ord2, (i, j) -> {
            if (val2[i] != val2[j]) {
                return Long.compare(val2[i], val2[j]);
            }
            return Long.compare(A[i], A[j]);
        });

        int[] pos2 = new int[N];
        for (int i = 0; i < N; i++) {
            pos2[ord2[i]] = i + 1;
        }

        Fenwick bit = new Fenwick(N);
        long inversions = 0;
        int processed = 0;

        for (int i = 0; i < N; i++) {
            int x = pos2[ord1[i]];
            int leq = bit.sum(x);
            inversions += (long) processed - leq;
            bit.add(x, 1);
            processed++;
        }

        System.out.println(inversions);
    }
}
